 1→//! Command-line interface for Bivvy.
 2→//!
 3→//! This module provides the CLI argument parsing using clap's derive macros
 4→//! and command implementations.
 5→//!
 6→//! # Architecture
 7→//!
 8→//! - [`args`] - Argument definitions using clap derive macros
 9→//! - [`commands`] - Command implementations
10→//! - [`session_wrapper`] - Session tracking integration
11→
12→pub mod args;
13→pub mod commands;
14→pub mod session_wrapper;
15→
16→pub use args::{
17→    Cli, Commands, ConfigArgs, HistoryArgs, InitArgs, LastArgs, LintArgs, ListArgs, RunArgs,
18→    StatusArgs,
19→};
20→pub use commands::{Command, CommandDispatcher, CommandResult};
21→pub use session_wrapper::SessionWrapper;
22→

 1→//! CLI command implementations.
 2→//!
 3→//! Each command implements the [`Command`] trait, which provides a uniform
 4→//! interface for executing commands and reporting results.
 5→//!
 6→//! # Architecture
 7→//!
 8→//! Commands are dispatched via [`CommandDispatcher`], which routes CLI
 9→//! subcommands to their implementations. This allows:
10→//! - Single binary with subcommands (`bivvy run`, `bivvy status`)
11→//! - Shared initialization logic
12→//! - Consistent global flag handling
13→
14→pub mod cache;
15→pub mod completions;
16→pub mod config;
17→pub mod dispatcher;
18→pub mod display;
19→pub mod feedback;
20→pub mod history;
21→pub mod init;
22→pub mod last;
23→pub mod lint;
24→pub mod list;
25→pub mod run;
26→pub mod status;
27→
28→pub use dispatcher::{Command, CommandDispatcher, CommandResult};
