 50→/// Trait for user interface interactions.
 51→///
 52→/// This trait allows mocking the UI in tests.
 53→pub trait UserInterface {
 54→    /// Get the current output mode.
 55→    fn output_mode(&self) -> OutputMode;
 56→
 57→    /// Display a message to the user.
 58→    fn message(&mut self, msg: &str);
 59→
 60→    /// Display a success message.
 61→    fn success(&mut self, msg: &str);
 62→
 63→    /// Display a warning message.
 64→    fn warning(&mut self, msg: &str);
 65→
 66→    /// Display an error message.
 67→    fn error(&mut self, msg: &str);
 68→
 69→    /// Show a prompt and get user input.
 70→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult>;
 71→
 72→    /// Start a spinner for an operation.
 73→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle>;
 74→
 75→    /// Start a spinner with leading indentation.
 76→    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
 77→        let _ = indent;
 78→        self.start_spinner(message)
 79→    }
 80→
 81→    /// Show a header/banner.
 82→    fn show_header(&mut self, title: &str);
 83→
 84→    /// Show progress (e.g., "Step 3 of 7").
 85→    fn show_progress(&mut self, current: usize, total: usize);
 86→
 87→    /// Check if running in interactive mode.
 88→    fn is_interactive(&self) -> bool;
 89→
 90→    /// Change the output mode at runtime.
 91→    fn set_output_mode(&mut self, mode: OutputMode);
 92→
 93→    /// Show a rich run header with app name, version, workflow, and step count.
 94→    fn show_run_header(
 95→        &mut self,
 96→        app_name: &str,
 97→        workflow: &str,
 98→        step_count: usize,
 99→        version: &str,
100→    ) {
101→        let _ = (workflow, step_count, version);
102→        self.show_header(app_name);
103→    }
104→
105→    /// Show/update workflow progress bar.
106→    fn show_workflow_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
107→        let _ = elapsed;
108→        self.show_progress(current, total);
109→    }
110→
111→    /// Finish and remove the workflow progress bar.
112→    fn finish_workflow_progress(&mut self) {}
113→
114→    /// Show a contextual hint to the user.
115→    fn show_hint(&mut self, hint: &str) {
116→        self.message(hint);
117→    }
118→
119→    /// Show a bordered error block with command, output, and optional hint.
120→    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
121→        self.error(command);
122→        if !output.is_empty() {
123→            self.message(output);
124→        }
125→        if let Some(h) = hint {
126→            self.show_hint(h);
127→        }
128→    }
129→
130→    /// Show a run summary with step results.
131→    fn show_run_summary(&mut self, summary: &RunSummary) {
132→        if summary.success {
133→            self.success(&format!(
134→                "Setup complete! ({} run, {} skipped)",
135→                summary.steps_run, summary.steps_skipped
136→            ));
137→        } else {
138→            self.error(&format!(
139→                "Setup failed at: {}",
140→                summary.failed_steps.join(", ")
141→            ));
142→        }
143→    }
144→}
