 30→
 31→impl CommandResult {
 32→    /// Create a success result.
 33→    pub fn success(stdout: String, stderr: String, duration: Duration) -> Self {
 34→        Self {
 35→            exit_code: Some(0),
 36→            stdout,
 37→            stderr,
 38→            duration,
 39→            success: true,
 40→        }
 41→    }
 42→
 43→    /// Create a failure result.
 44→    pub fn failure(
 45→        exit_code: Option<i32>,
 46→        stdout: String,
 47→        stderr: String,
 48→        duration: Duration,
 49→    ) -> Self {
 50→        Self {
 51→            exit_code,
 52→            stdout,
 53→            stderr,
