134→/// Execute a fix command with the step's environment and working directory.
135→pub fn run_fix(command: &str, project_root: &Path, env: &HashMap<String, String>) -> Result<bool> {
136→    let options = CommandOptions {
137→        cwd: Some(project_root.to_path_buf()),
138→        env: env.clone(),
139→        capture_stdout: false,
140→        capture_stderr: false,
141→        ..Default::default()
142→    };
143→
144→    let result = execute(command, &options)?;
145→    Ok(result.success)
146→}
