  1→//! Dependency graph for step execution ordering.
  2→
  3→use std::collections::{HashMap, HashSet, VecDeque};
  4→
  5→use crate::error::{BivvyError, Result};
  6→
  7→/// How to handle skipping a step that has dependents.
  8→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
  9→pub enum SkipBehavior {
 10→    /// Skip the step and all its dependents.
 11→    #[default]
 12→    SkipWithDependents,
 13→    /// Don't skip - run the step anyway.
 14→    RunAnyway,
 15→    /// Skip only this step, attempt to run dependents.
 16→    SkipOnly,
 17→}
 18→
 19→/// Represents the dependency relationships between steps.
 20→#[derive(Debug, Clone)]
 21→pub struct DependencyGraph {
 22→    /// Map of step name to its direct dependencies.
 23→    dependencies: HashMap<String, HashSet<String>>,
 24→    /// Map of step name to steps that depend on it.
 25→    dependents: HashMap<String, HashSet<String>>,
 26→    /// All step names in the graph.
 27→    steps: HashSet<String>,
 28→}
 29→
 30→impl DependencyGraph {
 31→    /// Create a new dependency graph builder.
 32→    pub fn builder() -> DependencyGraphBuilder {
 33→        DependencyGraphBuilder::new()
 34→    }
 35→
 36→    /// Get the direct dependencies of a step.
 37→    pub fn dependencies_of(&self, step: &str) -> Option<&HashSet<String>> {
 38→        self.dependencies.get(step)
 39→    }
 40→
 41→    /// Get steps that depend on the given step.
 42→    pub fn dependents_of(&self, step: &str) -> Option<&HashSet<String>> {
 43→        self.dependents.get(step)
 44→    }
 45→
 46→    /// Check if a step exists in the graph.
 47→    pub fn contains(&self, step: &str) -> bool {
 48→        self.steps.contains(step)
 49→    }
 50→
 51→    /// Get all step names.
 52→    pub fn steps(&self) -> &HashSet<String> {
 53→        &self.steps
 54→    }
 55→
 56→    /// Get the number of steps in the graph.
 57→    pub fn len(&self) -> usize {
 58→        self.steps.len()
 59→    }
 60→
 61→    /// Check if the graph is empty.
 62→    pub fn is_empty(&self) -> bool {
 63→        self.steps.is_empty()
 64→    }
 65→
 66→    /// Returns steps in topological order (dependencies before dependents).
 67→    ///
 68→    /// Returns an error if a cycle is detected.
 69→    pub fn topological_order(&self) -> Result<Vec<String>> {
 70→        // Count incoming edges for each node
 71→        let mut in_degree: HashMap<String, usize> = HashMap::new();
 72→        for step in &self.steps {
 73→            in_degree.insert(
 74→                step.clone(),
 75→                self.dependencies.get(step).map_or(0, |d| d.len()),
 76→            );
 77→        }
 78→
 79→        // Start with nodes that have no dependencies
 80→        let mut queue: VecDeque<String> = in_degree
 81→            .iter()
 82→            .filter(|(_, &degree)| degree == 0)
 83→            .map(|(step, _)| step.clone())
 84→            .collect();
 85→
 86→        let mut result = Vec::with_capacity(self.steps.len());
 87→
 88→        while let Some(step) = queue.pop_front() {
 89→            result.push(step.clone());
 90→
 91→            // Reduce in-degree for all dependents
 92→            if let Some(dependents) = self.dependents.get(&step) {
 93→                for dependent in dependents {
 94→                    if let Some(degree) = in_degree.get_mut(dependent) {
 95→                        *degree -= 1;
 96→                        if *degree == 0 {
 97→                            queue.push_back(dependent.clone());
 98→                        }
 99→                    }
100→                }

  1→//! Progress spinners.
  2→
  3→use indicatif::{ProgressBar, ProgressStyle};
  4→use std::collections::VecDeque;
  5→use std::sync::{Arc, Mutex};
  6→use std::time::Duration;
  7→
  8→use crate::shell::OutputLine;
  9→
 10→use super::theme::BivvyTheme;
 11→use super::SpinnerHandle;
 12→
 13→/// A progress spinner for long-running operations.
 14→pub struct ProgressSpinner {
 15→    bar: ProgressBar,
 16→    indent: usize,
 17→}
 18→
 19→impl ProgressSpinner {
 20→    /// Create a new spinner with a message.
 21→    pub fn new(message: &str) -> Self {
 22→        Self::with_indent(message, 0)
 23→    }
 24→
 25→    /// Create a new spinner with indentation.
 26→    pub fn with_indent(message: &str, indent: usize) -> Self {
 27→        let bar = ProgressBar::new_spinner();
 28→        let prefix = " ".repeat(indent);
 29→        bar.set_style(
 30→            ProgressStyle::default_spinner()
 31→                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
 32→                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
 33→                .unwrap(),
 34→        );
 35→        bar.set_message(message.to_string());
 36→        bar.enable_steady_tick(Duration::from_millis(80));
 37→
 38→        Self { bar, indent }
 39→    }
 40→
 41→    /// Create a spinner that doesn't show (for silent mode).
 42→    pub fn hidden() -> Self {
 43→        let bar = ProgressBar::hidden();
 44→        Self { bar, indent: 0 }
 45→    }
 46→
 47→    /// Get a clone of the inner progress bar for use in callbacks.
 48→    ///
 49→    /// This is useful for live output streaming: the cloned bar can be
 50→    /// passed to a callback running on another thread, and `set_message`
 51→    /// calls on it will update the spinner display in real-time.
 52→    pub fn bar_clone(&self) -> ProgressBar {
 53→        self.bar.clone()
 54→    }
 55→}
 56→
 57→impl SpinnerHandle for ProgressSpinner {
 58→    fn set_message(&mut self, msg: &str) {
 59→        self.bar.set_message(msg.to_string());
 60→    }
 61→
 62→    fn finish_success(&mut self, msg: &str) {
 63→        let prefix = " ".repeat(self.indent);
 64→        let theme = BivvyTheme::new();
 65→        self.bar
 66→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 67→        self.bar
 68→            .finish_with_message(format!("{}{}", prefix, theme.format_success(msg)));
 69→    }
 70→
 71→    fn finish_error(&mut self, msg: &str) {
 72→        let prefix = " ".repeat(self.indent);
 73→        let theme = BivvyTheme::new();
 74→        self.bar
 75→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 76→        self.bar
 77→            .finish_with_message(format!("{}{}", prefix, theme.format_error(msg)));
 78→    }
 79→
 80→    fn finish_skipped(&mut self, msg: &str) {
 81→        let prefix = " ".repeat(self.indent);
 82→        let theme = BivvyTheme::new();
 83→        self.bar
 84→            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
 85→        self.bar
 86→            .finish_with_message(format!("{}{}", prefix, theme.format_skipped(msg)));
 87→    }
 88→
 89→    fn progress_bar(&self) -> Option<ProgressBar> {
 90→        Some(self.bar.clone())
 91→    }
 92→}
 93→
 94→/// Create a step-style spinner.
 95→pub fn step_spinner(step_name: &str, description: &str) -> ProgressSpinner {
 96→    let msg = format!("{} - {}", step_name, description);
 97→    ProgressSpinner::new(&msg)
 98→}
