  1→//! Unified status vocabulary for consistent CLI output.
  2→//!
  3→//! `StatusKind` provides a single canonical set of status icons and
  4→//! colors used across all commands and display contexts. This replaces
  5→//! the previous split between theme-level symbols and display.rs brackets.
  6→
  7→use super::theme::BivvyTheme;
  8→
  9→/// Canonical status kinds used across all Bivvy output.
 10→#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
 11→pub enum StatusKind {
 12→    /// Operation completed successfully.
 13→    Success,
 14→    /// Operation failed.
 15→    Failed,
 16→    /// Operation was skipped.
 17→    Skipped,
 18→    /// Operation has not been run yet.
 19→    Pending,
 20→    /// Operation is currently running.
 21→    Running,
 22→    /// Operation is blocked (dependency failed).
 23→    Blocked,
 24→    /// Non-fatal warning.
 25→    Warning,
 26→}
 27→
 28→impl StatusKind {
 29→    /// Unicode icon for TTY output.
 30→    pub fn icon(self) -> &'static str {
 31→        match self {
 32→            Self::Success => "✓",
 33→            Self::Failed => "✗",
 34→            Self::Skipped => "○",
 35→            Self::Pending => "◌",
 36→            Self::Running => "◆",
 37→            Self::Blocked => "⊘",
 38→            Self::Warning => "⚠",
 39→        }
 40→    }
 41→
 42→    /// Bracketed text for non-TTY output.
 43→    pub fn bracketed(self) -> &'static str {
 44→        match self {
 45→            Self::Success => "[ok]",
 46→            Self::Failed => "[FAIL]",
 47→            Self::Skipped => "[skip]",
 48→            Self::Pending => "[pending]",
 49→            Self::Running => "[run]",
 50→            Self::Blocked => "[blocked]",
 51→            Self::Warning => "[warn]",
 52→        }
 53→    }
 54→
 55→    /// Styled icon string using the given theme.
 56→    pub fn styled(self, theme: &BivvyTheme) -> String {
 57→        let icon = self.icon();
 58→        match self {
 59→            Self::Success => theme.success.apply_to(icon).to_string(),
 60→            Self::Failed => theme.error.apply_to(icon).to_string(),
 61→            Self::Skipped => theme.dim.apply_to(icon).to_string(),
 62→            Self::Pending => theme.dim.apply_to(icon).to_string(),
 63→            Self::Running => theme.info.apply_to(icon).to_string(),
 64→            Self::Blocked => theme.warning.apply_to(icon).to_string(),
 65→            Self::Warning => theme.warning.apply_to(icon).to_string(),
 66→        }
 67→    }
 68→
 69→    /// Format a status line: styled icon + message.
 70→    pub fn format(self, theme: &BivvyTheme, msg: &str) -> String {
 71→        format!("{} {}", self.styled(theme), msg)
 72→    }
 73→
 74→    /// Format a status line for non-TTY: bracketed + message.
 75→    pub fn format_plain(self, msg: &str) -> String {
 76→        format!("{} {}", self.bracketed(), msg)
 77→    }
 78→}
 79→
 80→impl From<crate::state::StepStatus> for StatusKind {
 81→    fn from(status: crate::state::StepStatus) -> Self {
 82→        match status {
 83→            crate::state::StepStatus::Success => Self::Success,
 84→            crate::state::StepStatus::Failed => Self::Failed,
 85→            crate::state::StepStatus::Skipped => Self::Skipped,
 86→            crate::state::StepStatus::NeverRun => Self::Pending,
 87→        }
 88→    }
 89→}
 90→
 91→impl From<crate::steps::StepStatus> for StatusKind {
 92→    fn from(status: crate::steps::StepStatus) -> Self {
 93→        match status {
 94→            crate::steps::StepStatus::Pending => Self::Pending,
 95→            crate::steps::StepStatus::Running => Self::Running,
 96→            crate::steps::StepStatus::Completed => Self::Success,
 97→            crate::steps::StepStatus::Failed => Self::Failed,
 98→            crate::steps::StepStatus::Skipped => Self::Skipped,
 99→        }
100→    }
101→}
102→
103→impl From<crate::state::RunStatus> for StatusKind {
104→    fn from(status: crate::state::RunStatus) -> Self {
105→        match status {
106→            crate::state::RunStatus::Success => Self::Success,
107→            crate::state::RunStatus::Failed => Self::Failed,
108→            crate::state::RunStatus::Interrupted => Self::Warning,
109→        }
110→    }
111→}
112→
113→#[cfg(test)]
114→mod tests {
115→    use super::*;
116→
117→    #[test]
118→    fn icon_returns_unicode_symbols() {
119→        assert_eq!(StatusKind::Success.icon(), "✓");
120→        assert_eq!(StatusKind::Failed.icon(), "✗");
121→        assert_eq!(StatusKind::Skipped.icon(), "○");
122→        assert_eq!(StatusKind::Pending.icon(), "◌");
123→        assert_eq!(StatusKind::Running.icon(), "◆");
124→        assert_eq!(StatusKind::Blocked.icon(), "⊘");
125→        assert_eq!(StatusKind::Warning.icon(), "⚠");
126→    }
127→
128→    #[test]
129→    fn bracketed_returns_text_labels() {
130→        assert_eq!(StatusKind::Success.bracketed(), "[ok]");
131→        assert_eq!(StatusKind::Failed.bracketed(), "[FAIL]");
132→        assert_eq!(StatusKind::Skipped.bracketed(), "[skip]");
133→        assert_eq!(StatusKind::Pending.bracketed(), "[pending]");
134→        assert_eq!(StatusKind::Running.bracketed(), "[run]");
135→        assert_eq!(StatusKind::Blocked.bracketed(), "[blocked]");
136→        assert_eq!(StatusKind::Warning.bracketed(), "[warn]");
137→    }
138→
139→    #[test]
140→    fn styled_returns_string_with_icon() {
141→        let theme = BivvyTheme::plain();
142→        for kind in [
143→            StatusKind::Success,
144→            StatusKind::Failed,
145→            StatusKind::Skipped,
146→            StatusKind::Pending,
147→            StatusKind::Running,
148→            StatusKind::Blocked,
149→            StatusKind::Warning,
150→        ] {
151→            let styled = kind.styled(&theme);
152→            assert!(
153→                styled.contains(kind.icon()),
154→                "styled({:?}) missing icon",
155→                kind
156→            );
157→        }
158→    }
159→
160→    #[test]
161→    fn format_includes_icon_and_message() {
162→        let theme = BivvyTheme::plain();
163→        let result = StatusKind::Success.format(&theme, "install_deps");
164→        assert!(result.contains("✓"));
165→        assert!(result.contains("install_deps"));
166→    }
167→
168→    #[test]
169→    fn format_plain_uses_brackets() {
170→        let result = StatusKind::Failed.format_plain("build");
171→        assert_eq!(result, "[FAIL] build");
172→    }
173→
174→    #[test]
175→    fn from_state_step_status() {
176→        use crate::state::StepStatus;
177→
178→        assert_eq!(StatusKind::from(StepStatus::Success), StatusKind::Success);
179→        assert_eq!(StatusKind::from(StepStatus::Failed), StatusKind::Failed);
180→        assert_eq!(StatusKind::from(StepStatus::Skipped), StatusKind::Skipped);
181→        assert_eq!(StatusKind::from(StepStatus::NeverRun), StatusKind::Pending);
182→    }
183→
184→    #[test]
185→    fn from_steps_step_status() {
186→        use crate::steps::StepStatus;
187→
188→        assert_eq!(StatusKind::from(StepStatus::Pending), StatusKind::Pending);
189→        assert_eq!(StatusKind::from(StepStatus::Running), StatusKind::Running);
190→        assert_eq!(StatusKind::from(StepStatus::Completed), StatusKind::Success);
191→        assert_eq!(StatusKind::from(StepStatus::Failed), StatusKind::Failed);
192→        assert_eq!(StatusKind::from(StepStatus::Skipped), StatusKind::Skipped);
193→    }
194→
195→    #[test]
196→    fn from_run_status() {
197→        use crate::state::RunStatus;
198→
199→        assert_eq!(StatusKind::from(RunStatus::Success), StatusKind::Success);
200→        assert_eq!(StatusKind::from(RunStatus::Failed), StatusKind::Failed);
201→        assert_eq!(
202→            StatusKind::from(RunStatus::Interrupted),
203→            StatusKind::Warning
204→        );
205→    }
206→
207→    #[test]
208→    fn all_variants_have_unique_icons() {
209→        let icons: Vec<&str> = [
210→            StatusKind::Success,
211→            StatusKind::Failed,
212→            StatusKind::Skipped,
213→            StatusKind::Pending,
214→            StatusKind::Running,
215→            StatusKind::Blocked,
216→            StatusKind::Warning,
217→        ]
218→        .iter()
219→        .map(|k| k.icon())
220→        .collect();
221→
222→        // Warning and Blocked can share ⚠/⊘ — just ensure Success, Failed, etc. are distinct
223→        let mut unique = icons.clone();
224→        unique.sort();
225→        unique.dedup();
226→        assert_eq!(unique.len(), icons.len(), "All icons should be unique");
227→    }
228→
229→    #[test]
230→    fn all_variants_have_unique_brackets() {
231→        let brackets: Vec<&str> = [
232→            StatusKind::Success,
233→            StatusKind::Failed,
234→            StatusKind::Skipped,
235→            StatusKind::Pending,
236→            StatusKind::Running,
237→            StatusKind::Blocked,
238→            StatusKind::Warning,
239→        ]
240→        .iter()
241→        .map(|k| k.bracketed())
242→        .collect();
243→
244→        let mut unique = brackets.clone();
245→        unique.sort();
246→        unique.dedup();
247→        assert_eq!(
248→            unique.len(),
249→            brackets.len(),
250→            "All brackets should be unique"
251→        );
252→    }
253→}
